def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Parse history
    my = [h[0] for h in history]
    op = [h[1] for h in history]

    # Count opponent defections
    opp_def = 0
    for a in op:
        if a == 'D':
            opp_def += 1
    opp_c = n - opp_def

    # If opponent has never defected: cooperate fully. Defecting earlier tends
    # to be punished later by TFT-style opponents and give lower cumulative
    # score than sustained mutual cooperation.
    if opp_def == 0:
        return 'C'

    # If opponent never cooperated: defect forever.
    if opp_c == 0:
        return 'D'

    # Recent window behavior
    w = 8
    if n < w:
        r_op = op
    else:
        r_op = op[-w:]
    r_len = len(r_op)
    r_def = 0
    for a in r_op:
        if a == 'D':
            r_def += 1
    r_c = r_len - r_def

    # Consecutive trailing defections by opponent
    tail_def = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            tail_def += 1
        else:
            break

    # Consecutive trailing cooperations by opponent
    tail_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            tail_c += 1
        else:
            break

    last_my, last_op = history[-1]

    # If opponent is nearly always cooperative (e.g. ALLC, or recovering
    # from an early defection), cooperate. Punishing them is costly.
    if opp_def * 5 <= n:
        # exploit very lightly only when extremely late and safe
        remaining = 100 - n
        if remaining <= 1 and opp_def == 0:
            return 'D'
        return 'C'

    # Strong ongoing defection: defect back hard.
    if tail_def >= 2:
        # Opponent defected repeatedly; keep defecting.
        # But if opponent has overwhelmingly cooperative history, give an
        # occasional cooperative probe to re-establish mutual cooperation.
        if opp_c * 3 >= n * 2:
            if tail_def >= 4:
                # try one cooperative probe to reset
                if rng.random() < 0.25:
                    return 'C'
            return 'D'
        return 'D'

    # Opponent defected last round only once (tail_def == 1).
    if last_op == 'D':
        # If they have been mostly cooperative, retaliate briefly then
        # try to recover cooperation.
        if opp_c * 3 >= n * 2:
            # one-round retaliation
            return 'D'
        # If they defected more than a couple times overall, punish more.
        if opp_def * 3 >= n:
            return 'D'
        return 'D'

    # Opponent cooperated last round (tail_def == 0).
    # If recent window shows mostly defections, defect.
    if r_def * 2 > r_len:
        return 'D'

    # If opponent has very high cooperation rate overall, cooperate.
    if opp_c * 4 >= n * 3:
        return 'C'

    # If recent window shows heavy cooperation, cooperate.
    if r_c * 3 >= r_len * 2:
        return 'C'

    # Moderate-defection opponent: tit-for-tat-like with forgiveness.
    # If we defected last round and they cooperated, return to cooperation.
    if last_my == 'D' and last_op == 'C':
        return 'C'

    # Otherwise cooperate.
    return 'C'
